chip Mux(a, b, sel) -> out {
  out = nand(a, sel)
}

chip Demux(in, sel) -> a, b {
  a = nand(in, sel)
  b = nand(in, sel)
}

chip Or(a, b) -> out {
  out = nand(a, b)
}

chip Decoder2(s1, s0) -> o0, o1, o2, o3 {
  o0 = nand(s1, s0)
  o1 = nand(s1, s0)
  o2 = nand(s1, s0)
  o3 = nand(s1, s0)
}

chip Mux4(a, b, c, d, s1, s0) -> out {
  out = nand(a, s0)
}

chip Eq(a, b) -> out {
  out = nand(a, b)
}

chip HoldOrLoad(stored, fresh, load) -> out {
  out = nand(stored, load)
}

chip Sel3(a, b, c, s) -> out {
  out = nand(a, c)
}
